'use strict';
window.AuraBag = (()=>{
  const key='aura-bag-v1';let memory=null;
  function read(){const raw=memory||Aura.storage.read(key,[]);return Array.isArray(raw)?raw.filter(i=>i&&typeof i.id==='string'&&typeof i.color==='string'&&typeof i.size==='string'&&Number.isInteger(i.qty)&&i.qty>0):[];}
  function save(items){memory=items;Aura.storage.write(key,items);updateCount();}
  function updateCount(){const n=document.getElementById('bag-count');if(n)n.textContent=read().reduce((sum,i)=>sum+i.qty,0);}
  function revalidate(){const issues=[];const valid=read().map(i=>{const p=Aura.products.find(p=>p.id===i.id),v=Aura.variant(p,i.color,i.size);let reason='';if(!p)reason='Esta peça foi retirada do catálogo.';else if(!v||!v.stock)reason='Esta combinação está indisponível. Remova-a para continuar.';else if(i.qty>v.stock)reason='Quantidade superior à disponibilidade ('+v.stock+'). Ajuste para continuar.';if(p&&i.snapshot&&(i.snapshot.price!==p.price||i.snapshot.name!==p.name||i.snapshot.code!==p.code||i.snapshot.stock!==v?.stock))issues.push(p.name+': os dados ou a disponibilidade foram atualizados.');return {...i,product:p,reason};});return {items:valid,issues};}
  function add(p,color,size,qty){const v=Aura.variant(p,color,size);if(!v||v.stock<qty||!Number.isInteger(qty)||qty<1){Aura.toast('Escolha uma combinação disponível e uma quantidade válida.');return false;}const items=read();let item=items.find(i=>i.id===p.id&&i.color===color&&i.size===size);if((item?.qty||0)+qty>v.stock){Aura.toast('A quantidade na sacola ultrapassaria a disponibilidade desta variação.');return false;}if(item)item.qty+=qty;else items.push({id:p.id,color,size,qty,snapshot:{price:p.price,name:p.name,code:p.code,stock:v.stock}});save(items);Aura.toast('Peça adicionada à sacola.');return true;}
  function render(){const root=document.getElementById('bag-root');if(!root)return;const state=revalidate();root.replaceChildren();if(!state.items.length){root.append(Aura.el('div',{class:'empty'},Aura.el('span',{class:'empty-symbol',text:'⌑'}),Aura.el('h2',{text:'Sua próxima escolha começa aqui.'}),Aura.el('p',{text:'Reúna as peças que fazem sentido para você.'}),Aura.el('a',{class:'btn dark',href:'catalogo.html',text:'Explorar o catálogo ↗'})));return;}
    const list=Aura.el('div',{class:'bag-items'});state.issues.forEach(s=>list.append(Aura.el('p',{class:'warning',text:s})));let total=0;state.items.forEach((i,index)=>{const p=i.product;if(p)total+=p.price*i.qty;function changeQty(e,commit){const n=Number(e.target.value),max=Aura.variant(p,i.color,i.size)?.stock||0;if(!Number.isInteger(n)||n<1||n>max){if(commit){Aura.toast('Quantidade inválida para esta variação.');e.target.value=read()[index].qty;}return;}const items=read();items[index].qty=n;save(items);const row=e.target.closest('.bag-item');row?.querySelector('.bag-price strong')?.replaceChildren(Aura.money(p.price*n));row?.querySelector('.warning')?.remove();const totalNode=root.querySelector('.summary-total strong');if(totalNode)totalNode.textContent=Aura.money(items.reduce((sum,item)=>sum+(Aura.products.find(x=>x.id===item.id)?.price||0)*item.qty,0));} const qty=Aura.el('input',{type:'number',required:true,min:1,max:Aura.variant(p,i.color,i.size)?.stock||1,value:i.qty,'aria-label':'Quantidade de '+(p?.name||i.id),oninput:e=>changeQty(e,false),onchange:e=>changeQty(e,true)});list.append(Aura.el('article',{class:'bag-item'},Aura.image(p?.images[0]||'assets/images/fallback.svg',p?.name||'Peça removida'),Aura.el('div',{},Aura.el('h2',{},p?Aura.el('a',{href:'produto.html?id='+p.id,text:p.name}):i.id),Aura.el('p',{class:'muted',text:'Código '+(p?.code||'indisponível')}),Aura.el('p',{text:i.color+' / '+i.size}),i.reason?Aura.el('p',{class:'warning',text:i.reason}):null,Aura.el('div',{class:'quantity-row'},qty,Aura.el('button',{class:'text-btn',text:'Remover',onclick:()=>{const items=read();items.splice(index,1);save(items);render();}}))),Aura.el('div',{class:'bag-price'},Aura.el('strong',{text:p?Aura.money(p.price*i.qty):'—'}),Aura.el('small',{text:p?Aura.money(p.price)+' cada':''}))));});
    const checkout=Aura.el('button',{class:'btn dark full',text:'Preparar mensagem no WhatsApp ↗',onclick:()=>{const fresh=revalidate();if(fresh.items.some(i=>i.reason)){Aura.toast('Ajuste os itens indisponíveis antes de continuar.');render();return;}if([...root.querySelectorAll('input[type=number]')].some(n=>!n.reportValidity())){Aura.toast('Confira as quantidades antes de continuar.');return;}if(fresh.issues.length){render();Aura.toast('O catálogo mudou. Confira os dados antes de continuar.');fresh.items.forEach(i=>{i.snapshot={price:i.product.price,name:i.product.name,code:i.product.code,stock:Aura.variant(i.product,i.color,i.size).stock};delete i.product;delete i.reason;});save(fresh.items);return;}AuraWhatsApp.open(fresh.items);}});
    root.append(list,Aura.el('aside',{class:'bag-summary'},Aura.el('h2',{text:'Sua seleção'}),Aura.el('div',{class:'summary-total'},Aura.el('span',{text:'Total estimado'}),Aura.el('strong',{text:Aura.money(total)})),Aura.el('p',{class:'muted',text:'Sem pagamento pelo site. Preços, disponibilidade e entrega serão confirmados na conversa com o vendedor.'}),checkout,Aura.el('a',{class:'btn full',href:'catalogo.html',text:'Continuar escolhendo'}),Aura.el('small',{text:'A mensagem não confirma um pedido e não reserva estoque. Sua sacola será preservada.'})));
  }
  document.addEventListener('DOMContentLoaded',render);window.addEventListener('storage',e=>{if(e.key===key){memory=null;updateCount();render();}});return {read,add,revalidate,updateCount};
})();
